WHERE id IN ('news-aami-news-scoped', 'news-advamed-digital-health-scoped', 'news-africa-cdc-news-whole', 'news-ansm-news-scoped', 'news-bfarm-news-scoped', 'news-cleveland-clinic-health-essentials-sitemap', 'news-cleveland-clinic-newsroom-sitemap', 'news-council-eu-epsco-health-scoped', 'news-ec-dg-sante-health-scoped', 'news-ec-hera-scoped', 'news-ec-hta-htacg-target', 'news-ec-mdcg-target', 'news-ecdc-news-whole', 'news-edqm-news-whole', 'news-efsa-news', 'news-efsa-publications', 'news-eur-lex-mdr-ivdr-health-query', 'news-euractiv-health-scoped', 'news-fda-cdrh-ai-ml-device', 'news-fda-medwatch-supplements', 'news-fda-tainted-supplements', 'news-fierce-medtech-scoped', 'news-health-canada-devices-scoped', 'news-hhs-press-scoped', 'news-hma-news-whole', 'news-hpra-news-scoped', 'news-hpw-news-whole', 'news-hsa-medical-devices-scoped', 'news-imdrf-news-whole', 'news-jtc21-ai-health-gated', 'news-massdevice-news-whole', 'news-medica-sphere-medtech-scoped', 'news-medtech-europe-news-whole', 'news-mobihealthnews-ai-device-scoped', 'news-nhs-aidrs-news-scoped', 'news-observatory-news-whole', 'news-oecd-health-scoped', 'news-pmda-news-scoped', 'news-swissmedic-news-scoped', 'news-team-nb-news-whole', 'news-todays-dietitian-sitemap', 'news-un-news-health-scoped', 'news-www-medikalnews-whole')
